// Actual native22 highest-order characteristic analysis, not PDE evolution.
// Spatial derivative amplitudes and Omega weights are analysis inputs only.
#include "goal1_tensor_endpoint_amplitude.hpp"
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <string>
namespace cs=cubed_sphere;namespace te=cs::tensor_endpoint;namespace h=z4c::hyperboloidal;
using D=te::D;using J=cs::Jet;const int ia[6]={0,0,0,1,1,2},ib[6]={0,1,2,1,2,2};const int native[22]={0,1,2,3,4,5,6,18,19,20,21,8,9,10,11,12,13,7,17,14,15,16};
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short symbol input");char*e;Real x=std::strtod(s.c_str(),&e);if(*e||!std::isfinite(x))throw std::runtime_error("invalid symbol input");return x;}
void Seed(h::Z4cJet<D>&u,int c,int order,const Real xi[3],D e){for(int a=0;a<3;++a){if(c==0&&order==1)u.chi.d[a]+=e*D(xi[a]);if(c==7&&order==1)u.alpha.d[a]+=e*D(xi[a]);if(c>=8&&c<11&&order==1)u.beta.d[a][c-8]+=e*D(xi[a]);if(c>=1&&c<=6&&order==1){int i=ia[c-1],j=ib[c-1];u.metric.dg[a][i][j]+=e*D(xi[a]);if(i!=j)u.metric.dg[a][j][i]+=e*D(xi[a]);}if(c>=11&&c<17&&order==1){int i=ia[c-11],j=ib[c-11];u.a.dk[a][i][j]+=e*D(xi[a]);if(i!=j)u.a.dk[a][j][i]+=e*D(xi[a]);}if(c==17&&order==1)u.trace.d[a]+=e*D(xi[a]);if(c==18&&order==1)u.theta.d[a]+=e*D(xi[a]);if(c>=19&&order==1)u.lambda.d[a][c-19]+=e*D(xi[a]);for(int b=0;b<3;++b){if(c==0&&order==2)u.chi.dd[a][b]+=e*D(xi[a]*xi[b]);if(c==7&&order==2)u.alpha.dd[a][b]+=e*D(xi[a]*xi[b]);if(c>=8&&c<11&&order==2)u.beta.dd[a][b][c-8]+=e*D(xi[a]*xi[b]);if(c>=1&&c<=6&&order==2){int i=ia[c-1],j=ib[c-1];u.metric.ddg[a][b][i][j]+=e*D(xi[a]*xi[b]);if(i!=j)u.metric.ddg[a][b][j][i]+=e*D(xi[a]*xi[b]);}}}if(order==0){if(c>=11&&c<17){int i=ia[c-11],j=ib[c-11];u.a.k[i][j]+=e;if(i!=j)u.a.k[j][i]+=e;}if(c==17)u.trace.value+=e;if(c==18)u.theta.value+=e;if(c>=19)u.lambda.value[c-19]+=e;}}
struct Matrix{Real m[22][22]{},constraint[8][22]{};Real negative=0;};
Matrix Extract(const h::Z4cJet<Real>&base,const h::LayerPoint<Real>&p,const Real x[3],const Real xi[3],Real rho,Real step){Matrix out;auto ref=cs::typed_support::Constant<D>(p);J omega(rho);omega.d[0]=1;ref.omega=D(omega);auto c0=cs::native_endpoint::OuterConnection(x);rwm::Connection<D>connection{};connection.valid=true;for(int a=0;a<4;++a)for(int i=0;i<3;++i)for(int j=0;j<3;++j)connection.scaled[a][i][j]=D(c0.scaled[a][i][j].f);
for(int col=0;col<22;++col)for(int group=0;group<2;++group){auto u=cs::typed_support::Map<D>(base,[](int,Real v){return D(v);});J scale=(col==17||col==18)?omega:J(1);scale=scale*J(step);Seed(u,col,col<11?(group==0?1:2):(group==0?0:1),xi,D(J(0),scale));h::OmegaJet<D>o{};o.omega=D(omega);for(int i=0;i<3;++i){o.gradient[i]=D(p.domega[i]);for(int j=0;j<3;++j)o.hessian[i][j]=D(p.omega_hessian[i][j]);}h::SetStationaryOmegaNormal(u.alpha.value,u.beta.value,u.alpha.d,u.beta.d,o);auto f=h::ConformalRHS(u,o,D(10)/u.alpha.value,D(0));auto g=rwm::Gauge(ref,u,connection);if(!f.valid||!g.valid)throw std::runtime_error("invalid principal parts");auto regular=cs::native_endpoint::Rows(f.regular,g.regular),pole=cs::native_endpoint::Rows(f.pole,g.pole);
 for(int row=group?11:0;row<(group?22:11);++row){J r=regular[native[row]].a,s=pole[native[row]].a;Real value;if(rho>0){value=(r.f+s.f/rho)/(row==17||row==18?rho:1);}else if(row==17||row==18){out.negative=std::max({out.negative,std::abs(s.f),std::abs(r.f+s.d[0])});value=r.d[0]+s.h[0][0]/2;}else{out.negative=std::max(out.negative,std::abs(s.f));value=r.f+s.d[0];}out.m[row][col]=value/step;}
 // Separate exact native constraint extraction at appropriate differential orders.
 auto cu=cs::typed_support::Map<D>(base,[](int,Real v){return D(v);});Seed(cu,col,col<11?(group==0?2:1):(group==0?1:0),xi,D(J(0),scale));h::SetStationaryOmegaNormal(cu.alpha.value,cu.beta.value,cu.alpha.d,cu.beta.d,o);auto c=h::EvolvedConstraints(cu,o);if(!c.valid)throw std::runtime_error("invalid principal constraints");D rows[8]={c.hamiltonian,c.momentum[0],c.momentum[1],c.momentum[2],cu.theta.value,c.z4.z_covector[0],c.z4.z_covector[1],c.z4.z_covector[2]};for(int row=group?4:0;row<(group?8:4);++row){if(group==0&&((row==0&&col>=11)||(row>0&&col<11)))continue;J a=rows[row].a;Real value;if(rho>0)value=a.f/(row==0?rho*rho:(row<=4?rho:1));else value=row==0?a.h[0][0]/2:(row<=4?a.d[0]:a.f);out.constraint[row][col]=value/step;}
}return out;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read();Real x[3],xi[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});for(auto&v:xi)v=Read();h::LayerReference<Real>ref(1.,.5,{true,.05,.95});auto p=ref.At(x[0],x[1],x[2]);p.omega=0;auto geo=h::Geometry(u.metric);Real beta=0,norm=0;for(int i=0;i<3;++i){beta+=xi[i]*u.beta.value[i];for(int j=0;j<3;++j)norm+=u.chi.value*xi[i]*geo.inverse[i][j]*xi[j];}Real light=u.alpha.value*std::sqrt(norm);auto a=Extract(u,p,x,xi,0,1),half=Extract(u,p,x,xi,0,.5),finite=Extract(u,p,x,xi,.03,1),small=Extract(u,p,x,xi,.003,1);Real error=0,constraint_error=0,scale=1;for(int i=0;i<22;++i)for(int j=0;j<22;++j){error=std::max({error,std::abs(a.m[i][j]-finite.m[i][j]),std::abs(a.m[i][j]-small.m[i][j])});scale=std::max(scale,std::abs(a.m[i][j]));}for(int i=0;i<8;++i)for(int j=0;j<22;++j)constraint_error=std::max({constraint_error,std::abs(a.constraint[i][j]-finite.constraint[i][j]),std::abs(a.constraint[i][j]-small.constraint[i][j])});std::cout<<"certificate {\"id\":"<<id<<",\"negative_laurent\":"<<a.negative<<",\"finite_limit_relative\":"<<error/scale<<",\"constraint_limit_absolute\":"<<constraint_error<<"}\n";std::cout<<"case 0 1 "<<id<<" 0 "<<-beta-light<<" "<<-beta+light<<"\ninverse";for(const auto &row:geo.inverse)for(Real v:row)std::cout<<" "<<v;std::cout<<"\nnormal";for(Real v:xi)std::cout<<" "<<v;std::cout<<"\nconstraints\n";for(const auto &row:a.constraint){for(Real v:row)std::cout<<v<<" ";std::cout<<"\n";}for(int pass=0;pass<2;++pass){std::cout<<"matrix "<<(pass?.5:1)<<"\n";auto&m=pass?half:a;for(const auto &row:m.m){for(Real v:row)std::cout<<v<<" ";std::cout<<"\n";}}}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
